    text: "Connecting…",
  },
  connected: {
    dot: "bg-green-500",
    label: "Live updates connected",
    hint: "Live updates connected. Vite applies edits automatically.",
    text: "Connected",
  },
  disconnected: {
    dot: "bg-red-500",
    label: "Live updates disconnected",
    hint: "Dev server connection lost. Vite reconnects automatically.",
    text: "Disconnected",
  },
};

