#[allow(clippy::too_many_arguments)]
fn finish(
    raw: &SourceOutline,
    raw_topology: &curves::PreparedSubstitution<'_>,
    captured: &geometry::Parsed,
    fitted: &geometry::Parsed,
    upstream: &[FittedCommand],
    size_px: f64,
    anchors: &[AnchorV],
    prepared: &[geometry::PreppedPair],
    skipped: &[geometry::Skipped],
    waist: Waist,
    rel_med: f64,
    target: f64,
    matches: &[(Side, Side, f64)],
    quantized_zero: Vec<usize>,
    raw_crosses: Vec<serde_json::Value>,
) -> Result<FitResult, Error> {
    let skipped_json = || -> Vec<serde_json::Value> {
        skipped
            .iter()
            .map(|s| serde_json::json!({"pair": [s.pair.0, s.pair.1], "reason": s.reason}))
            .collect()
    };
    let waist_json =
        || serde_json::json!({"width": waist.width, "mid": waist.mid, "level": waist.level});
    let no = raw.oncurve.len();
    let base_all: Vec<[f64; 2]> = raw
        .oncurve
        .iter()
        .chain(raw.offcurve.iter())
        .copied()
        .collect();
    let up_all: Vec<[f64; 2]> = fitted
        .oncurve
        .iter()
        .chain(fitted.offcurve.iter())
        .copied()
        .collect();
    let base_flat = ravel(&base_all);
    let gaps_flat: Vec<f64> = up_all
        .iter()
        .zip(base_all.iter())
        .flat_map(|(u, b)| [u[0] - b[0], u[1] - b[1]])
        .collect();
    let flat_up = ravel(&up_all);
    let ControlOwnership {
        weld,
        quads,
        involved,
        cols,
    } = match ControlOwnership::prepare(raw, fitted, &base_all, &up_all, prepared) {
        Ok(ownership) => ownership,
        Err(OwnershipAbort::WeldMismatch) => {
            return Ok(abstain(
                upstream,
                "weld-mismatch",
                serde_json::json!({
                    "size_px": size_px,
                    "skipped": skipped_json(),
                    "waist": waist_json(),
                }),
            ));
        }
        Err(OwnershipAbort::NoFreeControls) => {
            return Ok(abstain(
                upstream,
                "no-free-controls",
                serde_json::json!({
                    "size_px": size_px,
                    "skipped": skipped_json(),
                    "waist": waist_json(),
                }),
            ));
        }
    };
    let (system, plain) = shape_objective_rows(raw, no, &involved, &base_all, size_px);
    // Shape rows keep the upstream gap unsubstituted: like the prototype
    // `soft_plain` block, their target is `-c`, so they regularize the
    // displacement itself. Only width and symmetry rows (the `soft_gap`
    // block) substitute the upstream gap into their constants.
    let mut soft = width_objective_rows(&system, prepared, anchors, size_px);
    let sym = symmetry_rows(&system, &base_flat, matches, waist.mid, 2.0 * target);
    if sym.is_empty() {
        return Ok(abstain(
            upstream,
            "phase-unconstrained",
            serde_json::json!({
                "size_px": size_px,
                "skipped": skipped_json(),
                "waist": waist_json(),
            }),
        ));
    }
    for (row, constant) in &sym {
        soft.push((row.clone(), *constant));
    }
    // Weld-folded reduction to free X columns.
    let reduce = |row: &[f64]| -> Vec<f64> {
        let mut full = row.to_vec();
        let mut keys: Vec<usize> = weld.keys().copied().collect();
        keys.sort();
        for dup in keys {
            let canon = weld[&dup];
            full[2 * canon] += full[2 * dup];
        }
        cols.iter().map(|v| full[2 * v]).collect()
    };
    let mat: Vec<Vec<f64>> = plain
        .iter()
        .chain(soft.iter())
        .map(|(row, _)| reduce(row))
        .collect();
    let rhs: Vec<f64> = plain
        .iter()
        .map(|(_, constant)| -constant)
        .chain(
            soft.iter()
                .map(|(row, constant)| -dotv(row, &gaps_flat) - constant),
        )
        h_active.push(*rhs);
    }
    Some((g_active, h_active))
}

fn collect_joint_constraints(
    parsed: &geometry::Parsed,
    up: &[[f64; 2]],
    involved: &HashSet<usize>,
    size_px: f64,
    hard: &mut Vec<HardRow>,
) -> Result<Vec<JointCheck>, &'static str> {
    let joints_map = scf::joints(parsed);
    let mut ordered_j: Vec<usize> = joints_map.keys().copied().collect();
    ordered_j.sort();
    let mut joint_checks: Vec<JointCheck> = Vec::new();
    for j in ordered_j {
        let mut occs = joints_map[&j].clone();
        occs.sort_by_key(|o| leg_far(o.prev, o.seg));
        for occ in &occs {
            let (iv, ov) = leg_far(occ.prev, occ.seg);
            if ![j, iv, ov].iter().any(|v| involved.contains(v)) {
                continue;
            }
            if occ.degenerate {
                return Err("degenerate-joint");
            }
            let curved_join = matches!(occ.prev, scf::SegRef::Quad { .. })
                || matches!(occ.seg, scf::SegRef::Quad { .. });
            let constrained = curved_join || occ.smooth;
            if constrained {
                match scf::g1_row(up, j, occ.prev, occ.seg, size_px, occ.smooth) {
                    Some((row, constant)) => hard.push(HardRow {
                        kind: "joint",
                        row,
                        constant,
                    }),
                    None => {
                        return Err("degenerate-leg");
                    }
                }
            }
            joint_checks.push(JointCheck {
                j,
                iv,
                ov,
                constrained,
                smooth: occ.smooth,
            });
        }
    }
    Ok(joint_checks)
}

fn rounded_hard_checks(
    hard: &[HardRow],
    point_count: usize,
    up_flat: &[f64],
    raw: &[[f64; 2]],
    up: &[[f64; 2]],
    cand: &[[f64; 2]],
) -> Result<Vec<serde_json::Value>, Vec<serde_json::Value>> {
    let raw_flat: Vec<f64> = raw.iter().flat_map(|p| [p[0], p[1]]).collect();
    let cand_flat: Vec<f64> = cand.iter().flat_map(|p| [p[0], p[1]]).collect();
    let mut hard_checks = Vec::new();
    for h in hard {
        let raw_error = (dot(&h.row, &raw_flat) - dot(&h.row, &up_flat) + h.constant).abs();
        let error = (dot(&h.row, &cand_flat) - dot(&h.row, &up_flat) + h.constant).abs();
        let allowance = (0..point_count)
            .filter(|v| raw[*v][0] != up[*v][0])
            .map(|v| h.row[2 * v].abs() / 128.0)
            .sum::<f64>();
        let ok = raw_error <= 1e-8 * (1.0 + h.constant.abs()) && error <= allowance + 1e-9;
        hard_checks.push(serde_json::json!({
            "kind": h.kind, "raw_error": raw_error, "rounded_error": error,
            "allowance": allowance, "ok": ok,
        }));
        if !ok {
            return Err(hard_checks);
        }
    }
    Ok(hard_checks)
}

